from fractions import Fraction
from sympy import symbols, apart

def lin(a):
    # the factor x - a, written the way you'd write it by hand
    if a == 0:
        return "x"
    if a > 0:
        return f"x - {a}"
    return f"x + {-a}"

def show(terms):
    # joins (coefficient, text) pairs into a sum like 2 ln|x - 1| - ln|x + 3|
    out = ""
    for c, t in terms:
        if c == 0:
            continue
        size = f"{abs(c)}"
        if abs(c) != int(abs(c)):
            size = f"({size})"
        piece = size + " " + t
        if t[:1] in ["", "x", "("]:
            piece = size + t
        if t[:2] == "1/":
            piece = size + t[1:]
        elif abs(c) == 1 and t != "":
            piece = t
        if c > 0:
            out = out + " + " + piece
        else:
            out = out + " - " + piece
    if out == "":
        return "0"
    if out[1] == "+":
        return out[3:]
    return "-" + out[3:]

def times(c, name):
    # c times an unknown, written 4A, -B, or B
    if c == 1:
        return name
    if c == -1:
        return "-" + name
    return f"{c}{name}"

x = symbols("x")

def split(label, p, q, a, b):
    # (px + q)/((x - a)(x - b)) = A/(x - a) + B/(x - b), by the cover-up method
    top = show([(p, "x"), (q, "")])
    A = Fraction(p * a + q, a - b)
    B = Fraction(p * b + q, b - a)
    print(label)
    print(f"  {top} = A({lin(b)}) + B({lin(a)})")
    print(f"  x = {a}: {p * a + q} = {times(a - b, 'A')}, so A = {A}")
    print(f"  x = {b}: {p * b + q} = {times(b - a, 'B')}, so B = {B}")
    print(f"  integral: {show([(A, f'ln|{lin(a)}|'), (B, f'ln|{lin(b)}|')])} + C")
    print(f"  sympy's apart: {apart((p * x + q) / ((x - a) * (x - b)))}")

