split("Example 2 · factored first: (5x - 4)/((x - 2)(x + 1))", 5, -4, 2, -1)
split("Example 4 · a constant on top: 1/((x - 3)(x + 3))", 0, 1, 3, -3)
split("Example 6 · a factor that cancels: (x - 1)/((x - 1)(x + 3))", 1, -1, 1, -3)
split("Example 10 · the tank: 6/((x + 1)(x + 3))", 0, 6, -1, -3)

