import math
from sympy import symbols, diff, simplify, log, atan

def lin(a):
    # the factor x - a, written the way you'd write it by hand
    if a == 0:
        return "x"
    if a > 0:
        return f"x - {a}"
    return f"x + {-a}"

def show(terms):
    # joins (coefficient, text) pairs into a sum like 2 ln|x - 1| - ln|x + 3|
    out = ""
    for c, t in terms:
        if c == 0:
            continue
        size = f"{abs(c)}"
        if abs(c) != int(abs(c)):
            size = f"({size})"
        piece = size + " " + t
        if t[:1] in ["", "x", "("]:
            piece = size + t
        if t[:2] == "1/":
            piece = size + t[1:]
        elif abs(c) == 1 and t != "":
            piece = t
        if c > 0:
            out = out + " + " + piece
        else:
            out = out + " - " + piece
    if out == "":
        return "0"
    if out[1] == "+":
        return out[3:]
    return "-" + out[3:]

def quadratic(b, c):
    return show([(1, "x^2"), (b, "x"), (c, "")])

def atan_text(h, k):
    # arctan((x + h)/k), written by hand
    inside = lin(-h)
    if k == 1 and h == 0:
        return "arctan x"
    if k == 1:
        return f"arctan({inside})"
    if h == 0:
        return f"arctan(x/{k})"
    return f"arctan(({inside})/{k})"

x = symbols("x")

def quad(label, A, B, b, c):
    # integral of (Ax + B)/(x^2 + bx + c) when b^2 - 4c < 0
    print(label)
    print(f"  discriminant {b * b - 4 * c} < 0, so {quadratic(b, c)} doesn't factor")
    h = Fraction(b, 2)
    k = math.isqrt(int(c - h * h))
    rest = B - A * h
    if h == 0:
        print(f"  no x term: k^2 = {c}, so k = {k}")
        print(f"  top: {show([(A, 'x'), (rest, '')])}")
    else:
        print(f"  complete the square: {quadratic(b, c)} = ({lin(-h)})^2 + {k * k}, so h = {h} and k = {k}")
        print(f"  top: {show([(A, f'({lin(-h)})'), (rest, '')])}")
    ln_part = Fraction(A, 2)
    atan_part = rest / k
    print(f"  ln gets {A}/2 = {ln_part}, arctan gets {rest}/{k} = {atan_part}")
    print(f"  integral: {show([(ln_part, f'ln({quadratic(b, c)})'), (atan_part, atan_text(h, k))])} + C")
    F = ln_part * log(x**2 + b*x + c) + atan_part * atan((x + h) / k)
    print(f"  check: F' minus the integrand simplifies to {simplify(diff(F, x) - (A*x + B) / (x**2 + b*x + c))}")

