    # the quotient by the power rule, then the two logs
    terms = [(q[i] / (len(q) - i), xpow(len(q) - i)) for i in range(len(q))]
    terms = terms + [(A, f"ln|{lin(a)}|"), (B, f"ln|{lin(b)}|")]
    return show(terms) + " + C"

n = int(input())
for i in range(n):
    # input().split() cuts a line at its spaces into a list of words
    P = [int(v) for v in input().split()]
    a, b = [int(v) for v in input().split()]
    while len(P) < 2:
        P = [0] + P
    Q = [1, -(a + b), a * b]
    q, rem = divide(P, Q)
    A = (rem[0] * a + rem[1]) / (a - b)
    B = (rem[0] * b + rem[1]) / (b - a)
    print(f"quotient {poly(q)}, remainder {poly(rem)}")
    print(f"A = {A}, B = {B}")
    print(integral_text(q, A, a, B, b))
